import sys
import heapq

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)

    N = next(it)
    T = next(it)

    types = [next(it) for _ in range(N)]
    prices = [next(it) for _ in range(N)]

    C = next(it)
    customers = [next(it) for _ in range(C)]

    heaps = [[] for _ in range(T + 1)]

    for t, p in zip(types, prices):
        heaps[t].append(p)

    global_heap = []

    for t in range(1, T + 1):
        if heaps[t]:
            heapq.heapify(heaps[t])
            global_heap.append((heaps[t][0], t))

    heapq.heapify(global_heap)

    ans = 0

    for u in customers:
        if u != 0:
            if heaps[u]:
                ans += heapq.heappop(heaps[u])
                if heaps[u]:
                    heapq.heappush(global_heap, (heaps[u][0], u))
        else:
            while global_heap:
                price, t = global_heap[0]
                if heaps[t] and heaps[t][0] == price:
                    break
                heapq.heappop(global_heap)

            if global_heap:
                price, t = heapq.heappop(global_heap)
                heapq.heappop(heaps[t])
                ans += price
                if heaps[t]:
                    heapq.heappush(global_heap, (heaps[t][0], t))

    print(ans)

if __name__ == "__main__":
